# ---- chao/indicators.py ----
"""TDX indicator functions over daily bars.

Each indicator takes pandas Series and integer periods and returns a Series
on the same index. Formulas can only call indicators registered in
INDICATORS; add new ones here without touching the formula engine.
Inputs are positional: one stock as a Series, or a panel of stocks as a
DataFrame with one column per stock (rows are each stock's own bars, so
rolling windows never mix stocks). Plain arrays from formula arithmetic are
accepted too.
"""


def series(x):
    if isinstance(x, (pd.Series, pd.DataFrame)):
        return x
    return pd.Series(x) if x.ndim == 1 else pd.DataFrame(x)


def MA(x, n):
    """Simple moving average; undefined until n bars exist."""
    return series(x).rolling(int(n), min_periods=int(n)).mean()


def REF(x, n):
    """Value n bars ago."""
    return series(x).shift(int(n))


def HHV(x, n):
    """Highest value over the last n bars."""
    return series(x).rolling(int(n), min_periods=int(n)).max()


def LLV(x, n):
    """Lowest value over the last n bars."""
    return series(x).rolling(int(n), min_periods=int(n)).min()


INDICATORS = {'MA': MA, 'REF': REF, 'HHV': HHV, 'LLV': LLV}


# ---- chao/settings.py ----
"""Typed configuration with one declared precedence chain.

An entry point declares its fields once: key, parser, default and a doc
line. Sources are flat dicts of raw values (GUI parameters, a config file,
command-line flags), listed highest precedence first. load() is the only
place values are merged: unknown keys and missing required keys are errors,
every value is parsed once, and the origin of each value is recorded.
"""

REQUIRED = object()


class Field(NamedTuple):
    key: str
    parse: Callable[[Any], Any]
    default: Any
    doc: str


class Loaded(NamedTuple):
    values: dict    # key -> parsed value; the entry point builds its record
    origins: dict   # key -> source name, or 'default'


class ConfigError(ValueError):
    pass


def text(value):
    return str(value)


def integer(value):
    return int(value)


def number(value):
    return float(value)


def id_list(value):
    """'1,2,7', [1, 2, 7] or a GUI number 3 -> tuple of ints."""
    if isinstance(value, (int, float)):
        return (int(value),)
    items = value.split(',') if isinstance(value, str) else value
    return tuple(int(x) for x in items if str(x).strip())


def path_map(value):
    """{'2': '/a'} or '2=/a,6=/b' -> {2: '/a', 6: '/b'}."""
    if isinstance(value, str):
        value = dict(item.split('=', 1) for item in value.split(',') if item.strip())
    return {int(k): str(v) for k, v in value.items()}


def load(fields, sources):
    """Merge sources [(name, {key: raw})], highest precedence first."""
    known = {f.key for f in fields}
    for name, values in sources:
        unknown = sorted(set(values) - known)
        if unknown:
            raise ConfigError('{}: unknown keys {}'.format(name, unknown))
    parsed, origins = {}, {}
    for field in fields:
        origin = next((name for name, values in sources if field.key in values), None)
        if origin is None:
            if field.default is REQUIRED:
                raise ConfigError('missing required setting {!r}: {}'.format(field.key, field.doc))
            parsed[field.key], origins[field.key] = field.default, 'default'
            continue
        raw = dict(sources)[origin][field.key]
        try:
            parsed[field.key] = field.parse(raw)
        except (TypeError, ValueError) as exc:
            raise ConfigError('{}: bad value {!r} for {!r}: {}'.format(origin, raw, field.key, exc))
        origins[field.key] = origin
    return Loaded(parsed, origins)


def describe(loaded):
    """One 'key = value  (origin)' line per setting, like git config --show-origin."""
    return ['{} = {!r}  ({})'.format(k, v, loaded.origins[k])
            for k, v in loaded.values.items()]


# ---- chao/market.py ----
"""Market data seen by the strategies, independent of where it comes from.

Symbols are exchange-qualified ('SH600000'). MarketData has two sources:
TDX files on Linux (chao.tdx_source) and the QMT client (chao.qmt_source).
Strategy code only receives a MarketData and plain pandas data from it.
"""


class MissingInput(ValueError):
    pass


# Index symbols used by the formulas.  000688 is both a Shenzhen stock and
# the Shanghai STAR 50 index, so indices are always spelled out in full.
INDEX_SYMBOLS = {'999999': 'SH999999', '399001': 'SZ399001', '399006': 'SZ399006',
                 '000688': 'SH000688', '899050': 'BJ899050'}


def equity_symbol(code):
    """Exchange-qualified symbol for a six-digit A-share stock code."""
    if code.startswith('6'):
        return 'SH' + code
    if code.startswith(('0', '3')):
        return 'SZ' + code
    if code.startswith(('43', '83', '87', '92')):
        return 'BJ' + code
    raise ValueError('cannot infer exchange for stock code {!r}'.format(code))


def board_index(symbol):
    """Index code TDX binds to INDEXC for a stock's board."""
    if symbol.startswith('BJ'):
        return '899050'
    if symbol.startswith(('SH688', 'SH689')):
        return '000688'
    if symbol.startswith(('SZ300', 'SZ301', 'SZ302')):
        return '399006'
    return '399001' if symbol.startswith('SZ') else '999999'


class MarketData(ABC):
    """Daily data for one snapshot of the market."""

    @abstractmethod
    def universe(self):
        """Exchange-qualified stock symbols."""

    @abstractmethod
    def bars(self, symbol):
        """Forward-adjusted daily bars: DatetimeIndex; open high low close amount."""

    @abstractmethod
    def index_closes(self):
        """{index code: daily close Series} for every code in INDEX_SYMBOLS."""

    @abstractmethod
    def name(self, symbol):
        """Current stock name, or None when unknown."""

    @abstractmethod
    def total_shares(self, symbol):
        """Total-share steps {YYYY-MM-DD: shares}; empty when unknown."""


class Context(NamedTuple):
    """Everything one run needs: settings, market data and the strategies."""
    settings: Any
    market: MarketData
    strategies: Dict[int, Any]


def share_series(steps, index):
    """FINANCE(1) on each bar from share-capital steps, or None."""
    if not steps:
        return None
    days = sorted(steps)
    step_dates = np.array(days, dtype='datetime64[ns]')
    values = np.array([float(steps[d]) for d in days])
    # Last step on or before each bar; bars before the first step get 0.
    pos = np.searchsorted(step_dates, np.asarray(index.values, dtype='datetime64[ns]'), side='right') - 1
    return pd.Series(np.where(pos >= 0, values[np.maximum(pos, 0)], 0.0), index=index)


# ---- chao/formulas.py ----
"""TDX strategy formulas: parse the formula text and evaluate it over bound data.

The engine knows the TDX expression syntax and nothing about any strategy.
Indicators come from chao.indicators; market data is bound by bind().
"""

# Output variables every strategy formula must define (TDX identifiers).
BUY_KEY, SELL_KEY = '\u4e70\u5165\u6761\u4ef6', '\u5356\u51fa\u6761\u4ef6'
ASSIGNMENT = re.compile('([A-Za-z][A-Za-z0-9]*|\u4e70\u5165\u6761\u4ef6|\u5356\u51fa\u6761\u4ef6)\\s*:=\\s*([^;]+);')
HEADER = re.compile('\\{\u7b56\u7565[0-9]+-([^}]+)\\}')


class Strategy(NamedTuple):
    id: int
    name: str
    assignments: List[Tuple[str, str]]   # (variable, TDX expression text)
    program: List[Tuple[str, Any]]       # (variable, parsed expression), parsed once


def parse_strategy(sid, text):
    """Parse one strategy formula file."""
    header = HEADER.search(text)
    body = re.sub(r'\{[^}]*\}', '', text)
    assignments = [(k, e.strip()) for k, e in ASSIGNMENT.findall(body)]
    keys = [k for k, _ in assignments]
    if BUY_KEY not in keys or SELL_KEY not in keys:
        raise ValueError('strategy {} must define {} and {}'.format(sid, BUY_KEY, SELL_KEY))
    program = [(k, parse(e)) for k, e in assignments]
    return Strategy(sid, header.group(1) if header else str(sid), assignments, program)


INDEX_REF = re.compile(r'"([0-9]+)\$C"')


def referenced_indices(strategy):
    """Index codes a formula reads explicitly, e.g. "399006$C"."""
    return {code for _, e in strategy.assignments for code in INDEX_REF.findall(e)}


def load_strategies(files):
    """{file name: formula text} -> {id: Strategy}; the id is the name prefix."""
    result = {}
    for file_name, text in files.items():
        sid = int(file_name.split('-', 1)[0])
        if sid in result:
            raise ValueError('duplicate strategy id {}'.format(sid))
        result[sid] = parse_strategy(sid, text)
    return result


def parse(expression):
    expression = INDEX_REF.sub(r'INDEX("\1")', expression)
    expression = re.sub(r'\bAND\b', 'and', expression)
    expression = re.sub(r'\bOR\b', 'or', expression)
    expression = re.sub(r'(?<![<>=!])=(?!=)', '==', expression)
    return ast.parse(expression.strip(), mode='eval').body


def literal(node):
    """Literal value of a number or string node; Python 3.6 has no ast.Constant."""
    kind = type(node).__name__
    if kind == 'Constant' or kind == 'NameConstant':
        return node.value
    if kind == 'Num':
        return node.n
    if kind == 'Str':
        return node.s
    raise ValueError('not a literal')


# Names whose values depend only on the stock's market data. A call that
# only refers to these (e.g. MA(CLOSE,20)) is computed once per stock and
# shared across strategies.
DATA_NAMES = frozenset(['CLOSE', 'HIGH', 'LOW', 'AMO', 'INDEXC', 'INDEX', 'FINANCE', 'NAMELIKE'])


def memo_key(node):
    """ast.dump of a call that only reads market data, else None; kept on the node."""
    if not hasattr(node, 'chao_memo_key'):
        names = {n.id for n in ast.walk(node) if isinstance(n, ast.Name)}
        node.chao_memo_key = ast.dump(node) if names <= DATA_NAMES | set(INDICATORS) else None
    return node.chao_memo_key


def evaluate(node, env, memo=None):
    if type(node).__name__ in ('Constant', 'Num', 'Str', 'NameConstant'):
        return literal(node)
    if isinstance(node, ast.Name): return env[node.id]
    if isinstance(node, ast.Call):
        if not isinstance(node.func,ast.Name) or node.keywords:
            raise ValueError('Unsupported formula call')
        key = memo_key(node) if memo is not None else None
        if key is not None and key in memo:
            return memo[key]
        value = env[node.func.id](*(evaluate(x,env,memo) for x in node.args))
        if key is not None:
            memo[key] = value
        return value
    if isinstance(node, ast.BoolOp):
        operands = [evaluate(x,env,memo) for x in node.values]
        result = operands[0]
        for operand in operands[1:]:
            result = result & operand if isinstance(node.op,ast.And) else result | operand
        return result
    if isinstance(node, ast.BinOp):
        return arithmetic(node.op, values_of(evaluate(node.left,env,memo)), values_of(evaluate(node.right,env,memo)))
    if isinstance(node,ast.Compare):
        # Compare plain arrays: identical results, far less pandas overhead.
        a=values_of(evaluate(node.left,env,memo)); result=True
        for op,right in zip(node.ops,node.comparators):
            b=values_of(evaluate(right,env,memo))
            # Same as np.isclose(a, b, rtol=0, atol=1e-10), without its overhead.
            with np.errstate(invalid='ignore'):
                close = (a == b) | (np.abs(np.subtract(a, b)) <= 1e-10)
            # Decimal bars and averages lose equality at the last binary bit;
            # every operator treats values within 1e-10 as equal.
            if isinstance(op,ast.Lt): value=np.logical_and(a<b, np.logical_not(close))
            elif isinstance(op,ast.LtE): value=(a<=b) | close
            elif isinstance(op,ast.Gt): value=np.logical_and(a>b, np.logical_not(close))
            elif isinstance(op,ast.GtE): value=(a>=b) | close
            elif isinstance(op,ast.Eq): value=np.logical_or(a==b, close)
            else: raise ValueError('Unsupported comparison')
            result=result & value; a=b
        return result
    raise ValueError('Unsupported formula AST: {}'.format(ast.dump(node)))


def arithmetic(op, a, b):
    """Element-wise IEEE arithmetic on plain arrays, as pandas would do."""
    with np.errstate(divide='ignore', invalid='ignore'):
        if isinstance(op, ast.Add): return a + b
        if isinstance(op, ast.Sub): return a - b
        if isinstance(op, ast.Mult): return a * b
        if isinstance(op, ast.Div): return a / b
    raise ValueError('Unsupported operator {}'.format(type(op).__name__))


def values_of(x):
    return x.values if isinstance(x, (pd.Series, pd.DataFrame)) else x


def reads(strategy):
    """Names a strategy's formulas refer to (e.g. NAMELIKE, FINANCE)."""
    return {n.id for _, node in strategy.program for n in ast.walk(node) if isinstance(n, ast.Name)}


def bind(close, high, low, amo, indexc, index_of, names, shares):
    """Formula names over a panel: one column per stock, rows are each stock's
    own bars. names holds a name or None per stock; shares is a panel with NaN
    where the share capital is unknown. A stock without a name never passes
    the ST exclusion; callers report it (see reads())."""
    def finance(field):
        if field != 1: raise ValueError('Unknown FINANCE field {}'.format(field))
        return shares
    def namelike(prefix):
        return np.array([float(n.startswith(prefix)) if n else np.nan for n in names])
    return dict(FINANCE=finance, INDEX=index_of, NAMELIKE=namelike,
                CLOSE=close, HIGH=high, LOW=low, AMO=amo, INDEXC=indexc)


def formula_environment(strategy, bound, memo=None):
    env = dict(INDICATORS)
    env.update(bound)
    for key, node in strategy.program:
        env[key] = evaluate(node, env, memo)
    return env


def signals(strategy, bound, shape, memo=None):
    """(buy, sell) boolean arrays of the given (bars, stocks) shape."""
    env = formula_environment(strategy, bound, memo)
    def flags(key):
        value = np.asarray(values_of(env[key]))
        if value.dtype != bool:
            raise ValueError('{} of strategy {} must be a condition'.format(key, strategy.id))
        return np.broadcast_to(value, shape)
    return flags(BUY_KEY), flags(SELL_KEY)


# ---- chao/qfq.py ----
"""TDX forward adjustment (qfq) from GBBQ ex-rights records.

TDX adjusts every bar before an ex-date with the affine transform
    P' = (P - C1/10 + C2*C4/10) / (1 + (C3 + C4)/10)
where, for GBBQ category 1, C1 is cash per 10 shares, C2 the rights-issue
price, C3 bonus shares per 10 and C4 rights shares per 10.  The composed
transform is evaluated exactly and rounded once, half away from zero, to the
fen.  GBBQ stores the fields as float32; TDX reads them at three decimals
(e.g. 1.799997 -> 1.800, 0.600215 -> 0.600).

An export only contains the ex-dates known when it was produced, so the
transform takes an explicit as-of date.  These rules reproduce 15,115 of the
15,118 reference trade prices; the three exceptions sit within 5e-5 of a
half-fen boundary.
"""

PRICE_COLUMNS = ('open', 'high', 'low', 'close')
XRXD = 1


class ExRights(NamedTuple):
    date: pd.Timestamp
    cash: Fraction          # C1, yuan per 10 shares
    rights_price: Fraction  # C2, yuan per share
    bonus: Fraction         # C3, shares per 10
    rights: Fraction        # C4, shares per 10


def field(value):
    text = str(np.float32(value))
    return Fraction(str(Decimal(text).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)))


def ex_rights(records, as_of):
    """Category-1 GBBQ records with ex-date on or before as_of, oldest first."""
    as_of = pd.Timestamp(as_of)
    events = []
    for row in records:
        if int(row['Category']) != XRXD:
            continue
        date = pd.Timestamp(row['Date']).tz_localize(None)
        if date <= as_of:
            events.append(ExRights(date, field(row['C1']), field(row['C2']),
                                   field(row['C3']), field(row['C4'])))
    return sorted(events, key=lambda e: e.date)


def _round_cents_exact(cents, a, b):
    """Round (cents/100)*a + b to cents, half away from zero, in exact rationals."""
    num = [c * a.numerator * b.denominator + 100 * b.numerator * a.denominator for c in cents.tolist()]
    den = a.denominator * b.denominator
    return np.array([(1 if n >= 0 else -1) * ((2 * abs(n) + den) // (2 * den)) for n in num],
                    dtype=np.int64)


# Double precision is off by far less than this many cents for any price, so
# only values this close to a half cent need the exact rational path.
HALF_CENT_MARGIN = 1e-6


def _round_cents(cents, a, b):
    """Same result as _round_cents_exact; floats decide every value that is
    not within HALF_CENT_MARGIN of a half cent."""
    value = cents * float(a) + 100 * float(b)
    magnitude = np.abs(value)
    rounded = (np.sign(value) * np.floor(magnitude + 0.5)).astype(np.int64)
    near = np.abs(magnitude - np.floor(magnitude) - 0.5) < HALF_CENT_MARGIN
    if near.any():
        rounded[near] = _round_cents_exact(cents[near], a, b)
    return rounded


def forward_adjust(raw, events):
    """Return raw OHLC bars forward-adjusted by events (see module doc)."""
    out = {k: raw[k].values.astype(float) for k in PRICE_COLUMNS}
    cents = {k: np.rint(out[k] * 100).astype(np.int64) for k in PRICE_COLUMNS}
    a, b = Fraction(1), Fraction(0)
    right = len(raw)
    for event in reversed(events):
        left = int(raw.index.searchsorted(event.date, side='left'))
        if left < right and (a, b) != (1, 0):
            for k in PRICE_COLUMNS:
                out[k][left:right] = _round_cents(cents[k][left:right], a, b) / 100
        right = min(right, left)
        scale = 1 + (event.bonus + event.rights) / 10
        shift = event.cash / 10 - event.rights_price * event.rights / 10
        # Compose P -> (P - shift) / scale after the existing transform.
        a, b = a / scale, b - a * shift / scale
    if right and (a, b) != (1, 0):
        for k in PRICE_COLUMNS:
            out[k][:right] = _round_cents(cents[k][:right], a, b) / 100
    return pd.DataFrame(out, index=raw.index, columns=list(PRICE_COLUMNS))


# ---- chao/signals.py ----
"""Signals of strategies on stocks, from any MarketData.

Stocks are evaluated together as a panel: one column per stock, rows aligned
on each stock's own last bar (never on dates, so a suspension does not open
a gap in a rolling window). Each indicator then runs once per panel instead
of once per stock. Results are bit-identical to evaluating each stock alone.
"""

MIN_BARS = 260  # MA(250) plus REF lookback


def stack(arrays, rows):
    """Bottom-aligned (rows, len(arrays)) panel; missing leading rows are NaN."""
    panel = np.full((rows, len(arrays)), np.nan)
    for j, values in enumerate(arrays):
        panel[rows - len(values):, j] = values
    return pd.DataFrame(panel)


def on_dates(series, dates):
    """series.reindex(dates).values for a sorted, unique series index."""
    known = series.index.values
    pos = np.searchsorted(known, dates.values)
    clipped = np.minimum(pos, len(known) - 1)
    hit = (pos < len(known)) & (known[clipped] == dates.values)
    return np.where(hit, series.values[clipped], np.nan)


class PanelView(NamedTuple):
    rows: int
    dates: List[Any]      # each stock's own bar dates (bottom-aligned in the panel)
    names: List[Any]
    shares: List[Any]     # FINANCE(1) per stock, or None
    bound: Dict[str, Any]


def bind_panel(market, symbols, frames):
    """Bind the formula names for stocks whose bars are given."""
    rows = max(len(f) for f in frames)
    dates = [f.index for f in frames]
    indices = market.index_closes()
    cached = {}
    def index_of(code):
        if code not in cached:
            cached[code] = stack([on_dates(indices[code], d) for d in dates], rows)
        return cached[code]
    names = [market.name(s) for s in symbols]
    shares = [share_series(market.total_shares(s), d) for s, d in zip(symbols, dates)]
    bound = bind(close=stack([f['close'].values for f in frames], rows),
                 high=stack([f['high'].values for f in frames], rows),
                 low=stack([f['low'].values for f in frames], rows),
                 amo=stack([f['amount'].values for f in frames], rows),
                 indexc=stack([on_dates(indices[board_index(s)], d) for s, d in zip(symbols, dates)], rows),
                 index_of=index_of, names=names,
                 shares=stack([np.full(len(d), np.nan) if x is None else x.values for x, d in zip(shares, dates)], rows))
    return PanelView(rows, dates, names, shares, bound)


def panel_signals(strategies, market, symbols):
    """Signals of the strategies on a batch of stocks.

    Returns (bars {symbol: DataFrame}, signals {symbol: {strategy id:
    buy/sell DataFrame}}, errors [(strategy, symbol, message)]). Stocks with
    fewer than MIN_BARS bars get no signals.
    """
    bars, errors = {}, []
    for symbol in symbols:
        try:
            bars[symbol] = market.bars(symbol)
        except (MissingInput, KeyError, ValueError) as exc:
            errors += [(s.id, symbol, '{}: {}'.format(type(exc).__name__, exc))
                       for s in strategies if strategy_universe(s.id, [symbol])]
    panel = [s for s in symbols if s in bars and len(bars[s]) >= MIN_BARS]
    if not panel:
        return bars, {}, sorted(errors)
    view = bind_panel(market, panel, [bars[s] for s in panel])
    rows, dates, names, shares, bound = view.rows, view.dates, view.names, view.shares, view.bound
    memo, result = {}, {s: {} for s in panel}
    for strategy in strategies:
        needs = reads(strategy)
        buy, sell = signals(strategy, bound, (rows, len(panel)), memo)
        for j, symbol in enumerate(panel):
            if not strategy_universe(strategy.id, [symbol]):
                continue
            if 'NAMELIKE' in needs and not names[j]:
                errors.append((strategy.id, symbol, 'MissingInput: NAMELIKE needs the stock name'))
                continue
            if 'FINANCE' in needs and shares[j] is None:
                errors.append((strategy.id, symbol, 'MissingInput: FINANCE(1) needs a share-capital series'))
                continue
            n = len(dates[j])
            result[symbol][strategy.id] = pd.DataFrame({'buy': buy[rows - n:, j], 'sell': sell[rows - n:, j]},
                                                       index=dates[j])
    return bars, result, sorted(errors)


def stock_signals(strategies, market, symbol):
    """(bars, {strategy id: buy/sell DataFrame}) for one stock; raises the
    first missing-data error, as the per-stock replay expects."""
    bars, result, errors = panel_signals(strategies, market, [symbol])
    if errors:
        raise MissingInput(errors[0][2])
    return bars[symbol], result.get(symbol, {})


def strategy_universe(sid, symbols):
    """Strategy 7 trades the Beijing exchange; strategies 1-6 trade SH and SZ."""
    return [s for s in symbols if (sid == 7) == s.startswith('BJ')]


# Board indices INDEXC can resolve to, per strategy universe (see board_index).
SH_SZ_BOARD_INDICES = {'999999', '399001', '399006', '000688'}
BJ_BOARD_INDICES = {'899050'}


def required_indices(strategies):
    """Index codes the given strategies can read, via INDEXC or "code$C"."""
    codes = set()
    for s in strategies:
        codes |= referenced_indices(s) | (BJ_BOARD_INDICES if s.id == 7 else SH_SZ_BOARD_INDICES)
    return codes


def strategies_for(context, symbol):
    return [s for _, s in sorted(context.strategies.items()) if strategy_universe(s.id, [symbol])]


def history_signals(context, symbols):
    """({symbol: {strategy id: buy/sell DataFrame}}, [(strategy, symbol, error)])
    for every enabled strategy on a batch of stocks."""
    _, result, errors = panel_signals([s for _, s in sorted(context.strategies.items())],
                                      context.market, symbols)
    return result, errors


def last_bar_signals(context, symbols):
    """Signals on each stock's last bar.

    Returns ([(date, strategy, symbol, 'buy'|'sell')], [(strategy, symbol, error)]).
    """
    result, errors = history_signals(context, symbols)
    found = []
    for symbol, by_strategy in result.items():
        for sid, sig in by_strategy.items():
            last = sig.iloc[-1]
            for side in ('buy', 'sell'):
                if last[side]:
                    found.append((sig.index[-1].strftime('%Y-%m-%d'), sid, symbol, side))
    return sorted(found), errors


# ---- chao/orders.py ----
"""Turn one day's signals into orders for one shared stock account.

Pure: account state and prices come in as data, orders go out as data.
Rules:
- Only stocks in `owned` (bought by chao) are ever sold, so holdings the
  user opened by hand are left alone. Sells use the sellable volume, which
  is how T+1 is respected.
- At most max_positions chao-owned stocks are held; a stock already in the
  account (owned or not), or with a chao order today, is never bought again.
  The order check keeps a restarted live run from repeating unfilled buys. Each buy targets
  total_asset / max_positions, capped by the cash left.
- Conflicts follow the strategy priority (highest first): buy candidates
  are taken in (priority, symbol) order, and a stock signalled by several
  strategies is attributed to the highest-priority one.
- Quantities are whole lots of 100 shares; STAR market (SH688/689) orders
  need at least 200 shares.
"""

LOT = 100
STAR_MIN = 200
CASH_BUFFER = 0.002  # left unspent per buy for fees and price drift


class Holding(NamedTuple):
    volume: int
    sellable: int


class Book(NamedTuple):
    cash: float
    total_asset: float
    holdings: Dict[str, Holding]   # every position in the account
    owned: Set[str]                # symbols chao bought and still tracks
    ordered: Set[str]              # symbols with a chao order today (live)


class Order(NamedTuple):
    side: str        # 'buy' or 'sell'
    symbol: str
    volume: int
    strategy: int


def to_cents(value, rounding=ROUND_HALF_UP):
    return float(Decimal(repr(float(value))).quantize(Decimal('0.01'), rounding=rounding))


# Continuous-auction price cage (\u6caa\u6df1 since 2023): a buy may not exceed the
# best ask by more than max(2%, 10 ticks); a sell may not undercut the best
# bid by more. Orders outside it are rejected.
CAGE_RATE, CAGE_TICKS = 0.02, 0.10


def limit_price(side, last, margin, down=None, up=None, ask=None, bid=None):
    """Limit price `margin` through the last price (above for a buy, below for
    a sell), in cents, inside the price cage around the best quote and the
    day's price limits when they are known."""
    if side == 'buy':
        price = to_cents(last * (1 + margin))
        if ask:
            price = min(price, max(to_cents(ask * (1 + CAGE_RATE), ROUND_FLOOR), to_cents(ask + CAGE_TICKS)))
        return min(price, float(up)) if up else price
    price = to_cents(last * (1 - margin))
    if bid:
        price = max(price, min(to_cents(bid * (1 - CAGE_RATE), ROUND_CEILING), to_cents(bid - CAGE_TICKS)))
    return max(price, float(down)) if down else price


def lot_volume(symbol, value, price):
    """Whole-lot shares worth at most value; 0 below the board minimum."""
    volume = int(value / price) // LOT * LOT
    minimum = STAR_MIN if symbol.startswith(('SH688', 'SH689')) else LOT
    return volume if volume >= minimum else 0


def plan_orders(signals, book, prices, max_positions, priority):
    """signals: [(strategy, symbol, 'buy'|'sell')]; prices: {symbol: buy price};
    priority: strategy ids, highest priority first."""
    rank = {sid: i for i, sid in enumerate(priority)}
    ordered = sorted(signals, key=lambda s: (rank.get(s[0], len(rank)), s[1], s[2]))
    orders: List[Order] = []
    sold = set()
    for sid, symbol, side in ordered:
        holding = book.holdings.get(symbol)
        if side == 'sell' and symbol in book.owned and holding and holding.sellable > 0 and symbol not in sold:
            orders.append(Order('sell', symbol, holding.sellable, sid))
            sold.add(symbol)
    held = {s for s, h in book.holdings.items() if h.volume > 0}
    slots = max_positions - len((held & book.owned) - sold)
    target = book.total_asset / max_positions
    cash = book.cash
    bought = set()
    for sid, symbol, side in ordered:
        if side != 'buy' or symbol in held or symbol in book.ordered or symbol in bought or slots <= 0:
            continue
        price = prices.get(symbol)
        if not price:
            continue
        volume = lot_volume(symbol, min(target, cash) * (1 - CASH_BUFFER), price)
        if volume == 0:
            continue
        orders.append(Order('buy', symbol, volume, sid))
        cash -= volume * price
        bought.add(symbol)
        slots -= 1
    return orders


# ---- chao/replay.py ----
"""Independent-symbol replay of the TDX backtester's single-precision ledger.

The ledger rules were derived from the fields of the TDX signal exports
(quantity, amount, fee, profit and available cash) and reproduce them to the
displayed cent.  TDX fills at the bar close without slippage and keeps every
money value as float32; displayed values are rounded only for output.
"""

# Direction labels are the literal values of the TDX export's signal column.
BUY, SELL, FLATTEN = '\u4e70\u5f00', '\u5356\u5e73', '\u5e73\u76d8'


def f32(value):
    return float(np.float32(value))


class ReplaySpec(NamedTuple):
    start: str
    end: str
    initial_cash: float
    buy_fee_rate: float
    sell_fee_rate: float


class Position(NamedTuple):
    quantity: int
    price: float
    fee: float
    cash_before: float


def buy_fill(cash, close, spec):
    """Return (position, cash_after, event_fields) or None when unaffordable."""
    price = f32(close)
    quantity = math.floor(cash / (price * f32(1 + spec.buy_fee_rate)))
    if quantity <= 0:
        return None
    amount = f32(quantity * price)
    fee = f32(amount * spec.buy_fee_rate)
    # TDX may overdraw by a fraction of a cent here and then clamps at zero.
    cash_after = max(0.0, f32(cash - amount - fee))
    position = Position(quantity, price, fee, cash)
    return position, cash_after, dict(price=price, quantity=quantity, amount=amount,
                                      fee=fee, profit=0.0, cash=cash_after)


def sell_fill(position, close, spec):
    """Return (cash_after, event_fields) for closing the whole position."""
    price = f32(close)
    amount = f32(position.quantity * price)
    fee = f32(amount * spec.sell_fee_rate)
    profit = f32(position.quantity * f32(price - position.price))
    cash_after = f32(f32(f32(position.cash_before - position.fee) + profit) - fee)
    return cash_after, dict(price=price, quantity=position.quantity, amount=amount,
                            fee=fee, profit=profit, cash=cash_after)


def replay(frame, signals, spec):
    """(events, summary) of one stock replayed with the TDX ledger rules."""
    bars = frame.loc[spec.start:spec.end]
    dates = bars.index
    closes = bars['close'].values.tolist()
    flags = signals.loc[dates]
    buys, sells = flags['buy'].values.tolist(), flags['sell'].values.tolist()
    cash = f32(spec.initial_cash); position = None; events = []
    equity = []
    for i, close in enumerate(closes):
        # TDX checks the buy before the sell, so a bar that meets both
        # conditions opens and closes a position at the same close.
        if not position and buys[i]:
            fill = buy_fill(cash, close, spec)
            if fill:
                position, cash, fields = fill
                events.append(dict(date=dates[i].strftime('%Y-%m-%d'), direction=BUY, **fields))
        if position and sells[i]:
            cash, fields = sell_fill(position, close, spec); position = None
            events.append(dict(date=dates[i].strftime('%Y-%m-%d'), direction=SELL, **fields))
        equity.append(cash + (position.quantity * close if position else 0.0))
    if position:
        cash, fields = sell_fill(position, closes[-1], spec); position = None
        events.append(dict(date=dates[-1].strftime('%Y-%m-%d'), direction=FLATTEN, **fields))
    curve = np.array(equity, dtype=float)
    sold = [e for e in events if e['direction'] != BUY]
    summary = {'closed_trades': len(sold), 'profitable_trades': sum(e['profit'] > 0 for e in sold),
               'net_profit': cash - spec.initial_cash, 'fees': sum(e['fee'] for e in events),
               'max_drawdown': float((np.maximum.accumulate(curve) - curve).max()) if len(curve) else 0.0}
    return events, summary


# ---- chao/tdx_report.py ----
"""Trade lists and summaries in the layout of the TDX signal exports.

The QMT backtest replays every (strategy, stock) pair with the TDX ledger
(chao.replay) and writes the trades in the same columns as the user's TDX
exports, so the two can be compared row by row.
"""

# Column names of the TDX export, kept verbatim so the files line up.
COLUMNS = ['\u54c1\u79cd\u4ee3\u7801', '\u54c1\u79cd\u540d\u79f0', '\u65f6\u95f4', '\u4fe1\u53f7', '\u4ef7\u683c(\u5143)', '\u4ea4\u6613\u91cf(\u80a1/\u624b)', '\u6210\u4ea4\u989d(\u5143)',
           '\u6536\u76ca(\u5143)', '\u624b\u7eed\u8d39(\u5143)', '\u53ef\u7528\u8d44\u91d1(\u5143)']


def cents(value):
    """A stored value rounded the way the export displays it."""
    return Decimal(repr(float(value))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def export_lines(events, names):
    """Tab-separated lines (header first) for one strategy's events."""
    lines = ['\t'.join(COLUMNS)]
    for e in sorted(events, key=lambda e: (e['code'], e['date'], e['direction'])):
        lines.append('\t'.join([e['code'], names.get(e['code']) or '', e['date'] + ' 00:00', e['direction'],
                                str(cents(e['price'])), str(int(e['quantity'])), str(cents(e['amount'])),
                                str(cents(e['profit'])), str(cents(e['fee'])), str(cents(e['cash']))]))
    return lines


def write_exports(directory, events_by_strategy, names):
    """One file per strategy: strategy-<id>-signals.tsv (UTF-8)."""
    os.makedirs(directory, exist_ok=True)
    paths = []
    for sid, events in sorted(events_by_strategy.items()):
        path = os.path.join(directory, 'strategy-{}-signals.tsv'.format(sid))
        with open(path, 'w', encoding='utf-8') as out:
            out.write('\n'.join(export_lines(events, names)) + '\n')
        paths.append(path)
    return paths


def summary_line(sid, summaries):
    "Totals over one strategy's stocks, like the export's \u7efc\u5408\u7edf\u8ba1 row."
    closed = sum(s['closed_trades'] for s in summaries)
    wins = sum(s['profitable_trades'] for s in summaries)
    return 'strategy={} trades={} wins={} win_rate={:.2f}% net_profit={:.2f} fees={:.2f}'.format(
        sid, closed, wins, 100.0 * wins / closed if closed else 0.0,
        sum(s['net_profit'] for s in summaries), sum(s['fees'] for s in summaries))


# ---- chao/qmt_source.py ----
"""MarketData from the built-in QMT client (a ContextInfo object).

This is the only module that knows QMT's API, symbol format and units. It
never imports QMT modules; the ContextInfo is passed in. Unadjusted bars are
forward-adjusted with chao.qfq, the algorithm verified against TDX.

Call shapes follow the official built-in API docs (dict.thinktrader.net,
innerApi); anything unexpected raises instead of being guessed at.

Data is read in layers:
- per stock, cached for the day and refreshed with reset_static(): ex-rights
  factors, total-share history, contract details;
- backtest: bars read with prefetch(symbols) in batches; only the current
  batch is kept, so a full history does not sit in memory;
- live: prepare() reads every stock's last HISTORY_BARS local bars (up to
  yesterday, final for the day) and adjusts them once; load_today() then
  only appends today's bar from the latest ticks.
"""

BAR_FIELDS = ['open', 'high', 'low', 'close', 'amount']
HISTORY_BARS = 400  # live: MA(250) plus REF lookback, with margin
ALL_BARS = -1       # backtest: every local bar up to the backtest end
TOTAL_CAPITAL = 'CAPITALSTRUCTURE.total_capital'  # shares
LIVE_SHARES_SINCE = '1990-01-01'  # live: today's total shares stand for the whole window
# Formula index code -> QMT code. TDX's 999999 is QMT's 000001.SH.
QMT_INDEX = {'999999': '000001.SH', '399001': '399001.SZ', '399006': '399006.SZ',
             '000688': '000688.SH', '899050': '899050.BJ'}
# get_divid_factors values, in the documented order: \u6bcf\u80a1\u80a1\u5229, \u6bcf\u80a1\u7ea2\u80a1,
# \u6bcf\u80a1\u8f6c\u589e, \u914d\u80a1, \u914d\u80a1\u4ef7, \u662f\u5426\u80a1\u6539, \u9664\u6743\u7cfb\u6570 (amounts per share); keys are
# epoch milliseconds.
DIVID_COLUMNS = ['interest', 'stockBonus', 'stockGift', 'allotNum', 'allotPrice', 'gugai', 'dr']


def to_qmt(symbol):
    """'SH600000' -> '600000.SH'."""
    return '{}.{}'.format(symbol[2:], symbol[:2])


def from_qmt(code):
    """'600000.SH' -> 'SH600000'."""
    number, market = code.split('.')
    return market + number


def three_decimals(value):
    return Fraction(str(Decimal(repr(float(value))).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)))


def per_ten(value):
    """Per-share quantity -> per-10-shares Fraction at TDX's three decimals."""
    return three_decimals(float(value) * 10)


def divid_events(factors):
    """QMT get_divid_factors -> every chao.qfq.ExRights, oldest first."""
    events = []
    for key, row in factors.items():
        if len(row) != len(DIVID_COLUMNS):
            raise MissingInput('unexpected get_divid_factors row {!r}'.format(row))
        values = dict(zip(DIVID_COLUMNS, row))
        events.append(ExRights(qmt_date(key), per_ten(values['interest']), three_decimals(values['allotPrice']),
                               per_ten(values['stockBonus']) + per_ten(values['stockGift']),
                               per_ten(values['allotNum'])))
    return sorted(events, key=lambda e: e.date)


def ex_rights_from_divid(factors, as_of):
    """Ex-rights events on or before as_of (GBBQ-style snapshot)."""
    return [e for e in divid_events(factors) if e.date <= pd.Timestamp(as_of)]


def qmt_date(value):
    """QMT time -> Timestamp: YYYYMMDD (bar index), epoch milliseconds
    (get_bar_timetag, get_divid_factors) or a date/datetime value."""
    if isinstance(value, (int, float, np.integer)) or (isinstance(value, str) and value.isdigit()):
        text = str(int(value))
        if len(text) == 8:
            return pd.Timestamp(text)
        utc = pd.Timestamp(int(text), unit='ms').tz_localize('UTC')
        return utc.tz_convert('Asia/Shanghai').normalize().tz_localize(None)
    return pd.Timestamp(value).normalize()


def name_text(value):
    """QMT returns GBK text; decode it when it arrives as bytes."""
    return value.decode('gbk') if isinstance(value, bytes) else str(value)


TICK_FIELDS = {'open': 'open', 'high': 'high', 'low': 'low', 'close': 'lastPrice', 'amount': 'amount'}


def tick_date(tick):
    """Day of a tick: timetag is '20240527 14:50:03' or epoch milliseconds."""
    stamp = tick.get('timetag')
    if isinstance(stamp, str) and len(stamp) >= 8 and stamp[:8].isdigit():
        return pd.Timestamp(stamp[:8])
    return qmt_date(stamp) if stamp else None


def with_tick(frame, tick, day):
    """frame with today's bar set from a get_full_tick tick, if the tick is
    from today and has traded; otherwise frame unchanged (None stays None)."""
    if not tick or float(tick.get('lastPrice') or 0) <= 0 or tick_date(tick) != day:
        return frame
    row = np.array([[float(tick[TICK_FIELDS[k]]) for k in BAR_FIELDS]])
    if frame is None:
        return pd.DataFrame(row, index=pd.DatetimeIndex([day]), columns=BAR_FIELDS)
    keep = frame.index < day
    return pd.DataFrame(np.vstack([frame[BAR_FIELDS].values[keep], row]),
                        index=frame.index[keep].append(pd.DatetimeIndex([day])), columns=BAR_FIELDS)


class Quote(NamedTuple):
    last: float
    ask: Optional[float]   # best ask, the buy price cage's reference
    bid: Optional[float]   # best bid, the sell price cage's reference


def first_price(levels):
    """Best level of a tick's askPrice/bidPrice (a list, or one number)."""
    for value in (levels if isinstance(levels, (list, tuple)) else [levels]):
        if value and float(value) > 0:
            return float(value)
    return None


def share_steps(column):
    """{YYYY-MM-DD: shares} at each change of a date-indexed share series."""
    steps, previous = {}, None
    for key, value in column.items():
        value = float(value)
        if value != previous:
            steps[qmt_date(key).strftime('%Y-%m-%d')] = value
            previous = value
    return steps


class QmtMarket(MarketData):
    def __init__(self, context_info, sectors, history_bars, end_time):
        self.C = context_info          # rebound by the entry on every QMT call
        self.sectors = sectors
        self.history_bars = history_bars
        self.end_time = end_time       # 'YYYYMMDD' in a backtest, '' live
        self.reset_static()
        self._raw = {}                 # backtest: unadjusted bars of the current batch
        self._index_closes = None
        self._prepared, self._prepared_index = {}, {}   # live: adjusted history, index bars
        self._today = None             # live: {symbol: prepared history + today's bar}

    def reset_static(self):
        self._events, self._shares, self._details = {}, {}, {}

    def detail(self, symbol):
        """Contract details: name and today's price limits. Current clients
        call it get_instrument_detail; older ones get_instrumentdetail."""
        if symbol not in self._details:
            read = getattr(self.C, 'get_instrument_detail', None) or self.C.get_instrumentdetail
            self._details[symbol] = read(to_qmt(symbol)) or {}
        return self._details[symbol]

    def price_limits(self, symbol):
        '(\u8dcc\u505c\u4ef7, \u6da8\u505c\u4ef7) for today, or (None, None) when unknown.'
        d = self.detail(symbol)
        return d.get('DownStopPrice') or None, d.get('UpStopPrice') or None

    def latest_quotes(self, symbols, today):
        """{symbol: Quote} from get_full_tick, for stocks traded today."""
        day = pd.Timestamp(today)
        ticks = self.C.get_full_tick([to_qmt(s) for s in symbols]) or {}
        quotes = {}
        for s in symbols:
            tick = ticks.get(to_qmt(s))
            if tick and float(tick.get('lastPrice') or 0) > 0 and tick_date(tick) == day:
                quotes[s] = Quote(float(tick['lastPrice']), first_price(tick.get('askPrice')),
                                  first_price(tick.get('bidPrice')))
        return quotes

    def latest_static_dates(self):
        """Latest ex-rights date and share-capital date read so far (or None)."""
        events = [e.date for es in self._events.values() for e in es]
        shares = [pd.Timestamp(d) for steps in self._shares.values() for d in steps]
        return max(events) if events else None, max(shares) if shares else None

    def _fetch(self, qmt_codes):
        data = self.C.get_market_data_ex(BAR_FIELDS, qmt_codes, period='1d', end_time=self.end_time,
                                         count=self.history_bars, dividend_type='none',
                                         fill_data=False, subscribe=False)
        frames = {}
        for code in qmt_codes:
            frame = data.get(code)
            if frame is None or frame.empty:
                continue
            frame = frame[BAR_FIELDS].copy()
            frame.index = pd.to_datetime([str(i)[:8] for i in frame.index], format='%Y%m%d')
            frames[code] = frame
        return frames

    def prefetch(self, symbols, index_codes):
        """Backtest: read the bars of one batch of stocks and the needed
        indices in one call."""
        qmt_index = {code: QMT_INDEX[code] for code in sorted(index_codes)}
        codes = [to_qmt(s) for s in symbols] + list(qmt_index.values())
        frames = self._fetch(codes)
        missing = [c for c in qmt_index.values() if c not in frames]
        if missing:
            raise MissingInput('no daily bars from QMT for indices {}; download them first'.format(missing))
        self._raw = {from_qmt(c): f for c, f in frames.items() if c not in qmt_index.values()}
        self._index_closes = {code: frames[c]['close'] for code, c in qmt_index.items()}

    def download_daily(self, symbols, index_codes, download):
        """Ask QMT to append any missing daily bars to local data. The call is
        non-blocking; prepare() checks what actually arrived."""
        for code in [to_qmt(s) for s in symbols] + [QMT_INDEX[c] for c in sorted(index_codes)]:
            download(code, '1d', '', '')  # an empty start downloads incrementally

    def prepare(self, symbols, index_codes, today, batch):
        """Live: every stock's local history before today, adjusted with the
        ex-rights known today, and the index bars. Returns {symbol or index
        code: last local bar date} for the readiness check."""
        day = pd.Timestamp(today)
        self._prepared, self._prepared_index, self._today = {}, {}, None
        qmt_index = {code: QMT_INDEX[code] for code in sorted(index_codes)}
        last = {}
        for i in range(0, len(symbols), batch):
            part = symbols[i:i + batch]
            codes = [to_qmt(s) for s in part] + (list(qmt_index.values()) if i == 0 else [])
            for code, frame in self._fetch(codes).items():
                frame = frame[frame.index < day]
                if frame.empty:
                    continue
                if code in qmt_index.values():
                    index = next(k for k, v in qmt_index.items() if v == code)
                    self._prepared_index[index] = frame
                    last[index] = frame.index[-1]
                    continue
                symbol = from_qmt(code)
                events = [e for e in self.ex_rights(symbol) if e.date <= day]
                adjusted = forward_adjust(frame, events)
                adjusted['amount'] = frame['amount']
                self._prepared[symbol] = adjusted
                last[symbol] = frame.index[-1]
        return last

    def load_today(self, symbols, today):
        """Live: prepared history plus today's bar from one get_full_tick
        call, for a batch of stocks and the indices. Today's bar is the
        unadjusted price, as forward adjustment leaves it."""
        day = pd.Timestamp(today)
        codes = [to_qmt(s) for s in symbols] + [QMT_INDEX[c] for c in sorted(self._prepared_index)]
        ticks = self.C.get_full_tick(codes) or {}
        self._today = {s: with_tick(self._prepared[s], ticks.get(to_qmt(s)), day)
                       for s in symbols if s in self._prepared}
        self._index_closes = {code: with_tick(frame, ticks.get(QMT_INDEX[code]), day)['close']
                              for code, frame in self._prepared_index.items()}

    def universe(self):
        codes = set()
        for sector in self.sectors:
            codes.update(self.C.get_stock_list_in_sector(sector))
        return sorted(from_qmt(code) for code in codes)

    def last_bar_date(self, symbol):
        """Live: date of the last bar loaded for today (None without data)."""
        frame = (self._today or {}).get(symbol)
        return None if frame is None else frame.index[-1]

    def raw_bars(self, symbol):
        raw = self._raw.get(symbol)
        if raw is None or raw.empty:
            raise MissingInput('no daily bars from QMT for {}'.format(to_qmt(symbol)))
        return raw

    def load_static(self, symbol):
        """Read and cache the per-stock data that does not change intraday."""
        if symbol not in self._events:
            self._events[symbol] = divid_events(self.C.get_divid_factors(to_qmt(symbol)) or {})
        self.detail(symbol)
        self.total_shares(symbol)

    def ex_rights(self, symbol):
        """Every ex-rights event of a stock, oldest first (cached for the day)."""
        if symbol not in self._events:
            self._events[symbol] = divid_events(self.C.get_divid_factors(to_qmt(symbol)) or {})
        return self._events[symbol]

    def bars(self, symbol):
        if self._today is not None:
            frame = self._today.get(symbol)
            if frame is None:
                raise MissingInput('no local daily bars for {}'.format(to_qmt(symbol)))
            return frame
        raw = self.raw_bars(symbol)
        if symbol not in self._events:
            self._events[symbol] = divid_events(self.C.get_divid_factors(to_qmt(symbol)) or {})
        events = [e for e in self._events[symbol] if e.date <= raw.index[-1]]
        adjusted = forward_adjust(raw, events)
        adjusted['amount'] = raw['amount']
        return adjusted

    def index_closes(self):
        if self._index_closes is None:
            raise MissingInput('index bars are read by prefetch()')
        return self._index_closes

    def name(self, symbol):
        return name_text(self.detail(symbol).get('InstrumentName', '')) or None

    def total_shares(self, symbol):
        """Total shares, {YYYY-MM-DD: shares} at each change.

        Live: FINANCE(1) is only read on today's bar, so today's TotalVolume
        from the contract details is the whole answer; it needs no financial
        download. Backtest: the history from get_financial_data, where one
        stock over a date range is a DataFrame indexed by date with one column
        per field; QMT returns a row per day and only the changes are kept."""
        if symbol not in self._shares and not self.end_time:
            shares = float(self.detail(symbol).get('TotalVolume') or 0)
            self._shares[symbol] = {LIVE_SHARES_SINCE: shares} if shares > 0 else {}
        if symbol not in self._shares:
            table = self.C.get_financial_data([TOTAL_CAPITAL], [to_qmt(symbol)], '19900101', '20991231',
                                              report_type='announce_time')
            if isinstance(table, pd.DataFrame) and table.shape[1] == 1:
                column = table.iloc[:, 0].dropna()
            elif isinstance(table, pd.DataFrame) and table.empty:
                column = pd.Series(dtype=float)
            else:
                raise MissingInput('unexpected get_financial_data result {!r}'.format(type(table)))
            self._shares[symbol] = share_steps(column)
        return self._shares[symbol]


# A long-listed stock with dividends and an index, read once at startup to
# confirm every API returns the shape this module parses.
PROBE_STOCK, PROBE_INDEX = '600000.SH', '000001.SH'
TICK_KEYS = ('timetag', 'lastPrice', 'open', 'high', 'low', 'amount', 'askPrice', 'bidPrice')
CODE = re.compile(r'^[0-9]{6}\.(SH|SZ|BJ)$')


def short(value):
    if isinstance(value, pd.DataFrame):
        return 'columns={} rows={} head={}'.format(list(value.columns), len(value), value.head(1).to_dict('records'))
    text = repr(value)
    return text if len(text) <= 200 else text[:200] + '...'


def financial_diagnosis(C):
    """Shown when the share table is all NaN: the other ways QMT may hold
    total shares, and where its local financial files are."""
    lines = []
    for field in (TOTAL_CAPITAL, '\u80a1\u672c\u8868.\u603b\u80a1\u672c'):
        for report_type in ('announce_time', 'report_time'):
            try:
                table = C.get_financial_data([field], [PROBE_STOCK], '20200101', '20991231', report_type=report_type)
                known = table.dropna() if hasattr(table, 'dropna') else table
                lines.append('  {} {}: {} non-NaN {}'.format(field, report_type, type(table).__name__, short(known)))
            except Exception as exc:  # each variant is reported, none decides anything
                lines.append('  {} {}: {}: {}'.format(field, report_type, type(exc).__name__, exc))
    calls = [('get_total_share', lambda: C.get_total_share(PROBE_STOCK)),
             ('TotalVolume', lambda: (getattr(C, 'get_instrument_detail', None) or C.get_instrumentdetail)(
                 PROBE_STOCK).get('TotalVolume'))]
    for name, call in calls:
        try:
            lines.append('  {}: {!r}'.format(name, call()))
        except Exception as exc:
            lines.append('  {}: {}: {}'.format(name, type(exc).__name__, exc))
    base = os.path.dirname(os.getcwd())
    lines.append('  cwd {}'.format(os.getcwd()))
    for path, dirs, files in os.walk(base):
        if path[len(base):].count(os.sep) >= 3:
            dirs[:] = []
        if 'financ' in os.path.basename(path).lower():
            lines.append('  dir {}: {} files {}'.format(path, len(files), files[:5]))
    return lines


def probe(C, sectors, end_time, live, clock):
    """Call each QMT data API once and check the shapes parsed above.
    Returns log lines; raises MissingInput showing the unexpected value."""
    lines = []
    def seen(name, value):
        lines.append('probe {}: {} {}'.format(name, type(value).__name__, short(value)))
    def expect(ok, name, value, wanted):
        if not ok:
            raise MissingInput('QMT {} returned {}; expected {}'.format(name, short(value), wanted))
    bars = C.get_market_data_ex(BAR_FIELDS, [PROBE_STOCK, PROBE_INDEX], period='1d', end_time=end_time, count=3,
                                dividend_type='none', fill_data=False, subscribe=False)
    for code in (PROBE_STOCK, PROBE_INDEX):
        frame = (bars or {}).get(code)
        seen('get_market_data_ex ' + code, frame)
        expect(isinstance(frame, pd.DataFrame) and not frame.empty and set(BAR_FIELDS) <= set(frame.columns)
               and all(str(i)[:8].isdigit() for i in frame.index), 'get_market_data_ex', frame,
               'a DataFrame of {} indexed by YYYYMMDD'.format(BAR_FIELDS))
    factors = C.get_divid_factors(PROBE_STOCK)
    seen('get_divid_factors', factors)
    expect(isinstance(factors, dict) and factors, 'get_divid_factors', factors,
           '{epoch ms: [7 per-share values]} with past dividends')
    divid_events(factors)  # raises on a wrong row shape
    if not live:  # live reads today's total shares from the contract details
        table = C.get_financial_data([TOTAL_CAPITAL], [PROBE_STOCK], '19900101', '20991231',
                                     report_type='announce_time')
        seen('get_financial_data', table)
        expect(isinstance(table, pd.DataFrame) and table.shape[1] == 1 and not table.empty, 'get_financial_data',
               table, 'a one-column DataFrame indexed by date')
        qmt_date(table.index[-1])
        known = table.iloc[:, 0].dropna()
        if known.empty:
            raise MissingInput('QMT get_financial_data returned {}; expected total_capital values; all are NaN, '
                               'so download \u8d22\u52a1\u6570\u636e in \u6570\u636e\u7ba1\u7406 first (the backtest needs the share history). '
                               'Diagnosis:\n{}'.format(short(table), '\n'.join(financial_diagnosis(C))))
        lines.append('probe total shares {}: {} on {}, {} changes (shares; 600000.SH is about 3.3e10)'.format(
            PROBE_STOCK, known.iloc[-1], known.index[-1], len(share_steps(known))))
    read = getattr(C, 'get_instrument_detail', None) or C.get_instrumentdetail
    detail = read(PROBE_STOCK)
    seen('get_instrument_detail', detail)
    expect(isinstance(detail, dict) and detail.get('InstrumentName') and 'UpStopPrice' in detail
           and 'DownStopPrice' in detail, 'get_instrument_detail', detail,
           'a dict with InstrumentName, UpStopPrice, DownStopPrice')
    if live:
        expect(float(detail.get('TotalVolume') or 0) > 0, 'get_instrument_detail', detail,
               'TotalVolume, the total shares FINANCE(1) reads live')
    for sector in sectors:
        codes = C.get_stock_list_in_sector(sector)
        seen('get_stock_list_in_sector ' + sector, len(codes or []))
        expect(codes and all(CODE.match(c) for c in codes), 'get_stock_list_in_sector ' + sector,
               (codes or [])[:5], "a non-empty list of codes like '600000.SH'")
    if live:
        tick = (C.get_full_tick([PROBE_STOCK]) or {}).get(PROBE_STOCK)
        seen('get_full_tick', tick)
        expect(isinstance(tick, dict) and all(k in tick for k in TICK_KEYS), 'get_full_tick', tick,
               'a dict with {}'.format(TICK_KEYS))
        lines.append('probe clock: machine {} latest tick {}'.format(clock, tick.get('timetag')))
    return lines


# ---- chao/qmt_trade.py ----
"""Account state and order placement through QMT's trading API.

Like chao.qmt_source, this receives the ContextInfo and imports nothing
from QMT. passorder and get_trade_detail_data are QMT globals, so they are
passed in as an `api` object; tests pass a fake.
"""

STOCK_BUY, STOCK_SELL = 23, 24
BY_SHARES = 1101      # volume is a share count
LATEST_PRICE = 5      # backtest: fill at the bar close
LIMIT_PRICE = 11      # live: a specified limit price
STRATEGY_NAME = 'chao'
# quickTrade 2 sends the order on the bar that produced the signal, also on
# historical bars in a backtest; 0 would wait for the next bar.
QUICK = 2


class QmtApi:
    """The QMT globals the trade layer uses."""

    def __init__(self, passorder, get_trade_detail_data):
        self.passorder = passorder
        self.get_trade_detail_data = get_trade_detail_data


def read_book(api, account_id, owned, live):
    accounts = api.get_trade_detail_data(account_id, 'STOCK', 'ACCOUNT')
    if not accounts:
        raise RuntimeError('QMT returned no account data for {!r}'.format(account_id))
    holdings = {}
    for p in api.get_trade_detail_data(account_id, 'STOCK', 'POSITION'):
        symbol = p.m_strExchangeID + p.m_strInstrumentID
        holdings[symbol] = Holding(int(p.m_nVolume), int(p.m_nCanUseVolume))
    # Forget owned symbols that are no longer held (sold, or never filled).
    held = {s for s, h in holdings.items() if h.volume > 0}
    # Today's orders placed under chao's strategy name (live only).
    ordered = ({o.m_strExchangeID + o.m_strInstrumentID
                for o in api.get_trade_detail_data(account_id, 'STOCK', 'ORDER', STRATEGY_NAME)}
               if live else set())
    return Book(float(accounts[0].m_dAvailable), float(accounts[0].m_dBalance), holdings,
                set(owned) & held, ordered)


def place(api, C, account_id, order, price=None):
    """Send an order: at a limit price when given (live), else at the latest
    price (backtest, where that is the bar close)."""
    op = STOCK_BUY if order.side == 'buy' else STOCK_SELL
    pr_type, value = (LATEST_PRICE, -1) if price is None else (LIMIT_PRICE, price)
    api.passorder(op, BY_SHARES, account_id, to_qmt(order.symbol), pr_type, value, order.volume,
                  STRATEGY_NAME, QUICK, 'chao-s{}'.format(order.strategy), C)


class Ledger:
    """The stocks chao bought: the strategy that bought each one and whether
    its sell is pending. A pending sell is retried every day until the
    position is gone, as a TDX backtest sell always completes. Persisted as
    JSON {symbol: {"strategy": id, "selling": bool}} when a path is set."""

    def __init__(self, path):
        self.path = Path(path) if path else None
        self.entries = json.loads(self.path.read_text()) if self.path and self.path.exists() else {}

    @property
    def owned(self):
        return set(self.entries)

    def owner(self, symbol):
        return self.entries[symbol]['strategy']

    def selling(self, symbol):
        return self.entries[symbol]['selling']

    def keep(self, held):
        """Forget symbols no longer held (sold, or a buy that never filled)."""
        self.entries = {s: e for s, e in self.entries.items() if s in held}
        self.save()

    def bought(self, symbol, strategy):
        self.entries[symbol] = {'strategy': strategy, 'selling': False}
        self.save()

    def sell(self, symbol):
        self.entries[symbol]['selling'] = True
        self.save()

    def save(self):
        if self.path:
            self.path.write_text(json.dumps(self.entries, sort_keys=True))


